,"CREATE OR REPLACE PROCEDURE sp_g1t_m4r_a8s(a6e_5 text, OUT r7t_6 refcursor)

  CREATE OR REPLACE EDITIONABLE FUNCTION "a62"."g1t_j2n_f1c" (ip_r1c VARCHAR2) RETURN CLOB AS

        l9t_3   x5e;
        l2l          LONG;
        l6a      x5e;
        l6t      DBMS_XMLGEN.CTXHANDLE;
        l_r1t_c2b    CLOB;
        d2c_c1r      NUMBER;
        l_d3r_t1b   DBMS_SQL.DESC_TAB2;
        l_n1m_c2s    NUMBER;
        l_h4r_c2b CLOB;
        l_r1w_d2a    VARCHAR2(100);
        l_ip_r1c      SYS_REFCURSOR;
        l_e2c_c2m   VARCHAR2(250);
BEGIN
        l_e2c_c2m := 'SELECT ' || ip_r1c || ' FROM d2l';

        EXECUTE IMMEDIATE l_e2c_c2m
                INTO l_ip_r1c;

        l_h4r_c2b := '{"m6a":[';
        d2c_c1r      := DBMS_SQL.TO_CURSOR_NUMBER(l_ip_r1c);

        DBMS_SQL.DESCRIBE_COLUMNS2(d2c_c1r
                                  ,l_n1m_c2s
                                  ,l_d3r_t1b);

        FOR I IN 1 .. l_n1m_c2s
        LOOP
                CASE
                        WHEN l_d3r_t1b(I).c1l_t2e IN (2
                                         ,8) THEN
                                l_r1w_d2a := '{"n2e":"' || l_d3r_t1b(I)
                                             .c1l_n2e || '","TYPE":"NUMBER"},';
                        WHEN l_d3r_t1b(I).c1l_t2e = 12 THEN
                                l_r1w_d2a := '{"n2e":"' || l_d3r_t1b(I)
                                             .c1l_n2e || '","TYPE":"DATE"},';
                        ELSE
                                l_r1w_d2a := '{"n2e":"' || l_d3r_t1b(I)
                                             .c1l_n2e || '","TYPE":"TEXT"},';
                END CASE;
                DBMS_LOB.WRITEAPPEND(l_h4r_c2b
                                    ,LENGTH(l_r1w_d2a)
                                    ,l_r1w_d2a);
        END LOOP;
        l_h4r_c2b := RTRIM(l_h4r_c2b
                              ,',') || '],"DATA":';

        EXECUTE IMMEDIATE l_e2c_c2m
                INTO l_ip_r1c;
        l6t := DBMS_XMLGEN.NEWCONTEXT(l_ip_r1c);
        DBMS_XMLGEN.SETNULLHANDLING(l6t
                                   ,1);
        l6a := DBMS_XMLGEN.GETXMLTYPE(l6t
                                          ,DBMS_XMLGEN.NONE);

        l2l := '<?x1l VERSION="1.0" ENCODING="i1o-8859-1"?>
<x1l_2:s8t VERSION="1.0"
  x3s_2:x1l_2="h2p://w1w.w3.o1g/1999/x1l_2/TRANSFORM">
<x1l_2:OUTPUT METHOD="h2l"/>
<x1l_2:TEMPLATE MATCH="/">[<x1l_2:FOR-EACH SELECT="/r4t_5/*">
  {<x1l_2:FOR-EACH SELECT="./*">
    "<x1l_2:VALUE-OF SELECT="n2e()"/>":"<x1l_2:VALUE-OF SELECT="TEXT()"/>"<x1l_2:c4e_5>
      <x1l_2:WHEN t2t_5="POSITION()!= LAST()">,</x1l_2:WHEN>
    </x1l_2:c4e_5>
   </x1l_2:FOR-EACH>
  }<x1l_2:c4e_5>
      <x1l_2:WHEN t2t_5="POSITION() != LAST()">,</x1l_2:WHEN>
    </x1l_2:c4e_5>
   </x1l_2:FOR-EACH>
]}]}</x1l_2:TEMPLATE></x1l_2:s8t>';

        l9t_3 := l6a.TRANSFORM(x5e(l2l));
        l_r1t_c2b  := l9t_3.g8l();
        l_r1t_c2b  := REPLACE(l_r1t_c2b
                              ,'_x30_'
                              ,' ');
        DBMS_LOB.WRITEAPPEND(l_h4r_c2b
                            ,LENGTH(l_r1t_c2b)
                            ,l_r1t_c2b);
        RETURN l_h4r_c2b;
EXCEPTION
        WHEN OTHERS THEN
                DBMS_OUTPUT.PUT_LINE(SQLERRM);
                DBMS_OUTPUT.PUT_LINE(DBMS_UTILITY.FORMAT_ERROR_BACKTRACE);
                RETURN NULL;
END g1t_j2n_f1c;,"CREATE OR REPLACE FUNCTION a62.g1t_j2n_f1c(ip_r1c TEXT) RETURNS TEXT AS $$

  CREATE OR REPLACE EDITIONABLE PROCEDURE "c4a_e5k"."u65_p1c_ma_s1c_u1d" AS

MESSAGE VARCHAR2(512);e3r_2 VARCHAR2(512);

c1t_2 NUMBER(30);



CURSOR c1r_t2p_t3e IS

                SELECT e1t_o1j_id,u1d_s4e FROM u65_m3h_s1c_u1d;

v_n1m NUMBER :=0;

TYPE t1p_s1c_c1l IS TABLE OF VARCHAR2(4000);
TYPE t1p_o1j_c1l IS TABLE OF NUMBER(15);


s1c_c1l t1p_s1c_c1l;

o1j_c1l t1p_o1j_c1l;

BEGIN

OPEN c1r_t2p_t3e;

LOOP

FETCH c1r_t2p_t3e BULK COLLECT INTO o1j_c1l,s1c_c1l LIMIT 10000;




COMMIT;

FORALL I IN 1..o1j_c1l.COUNT

 UPDATE e1t_e5t_m3h_t3e a SET a.e1t_s4e = s1c_c1l(I) WHERE a.o1j_id = o1j_c1l(I);

EXIT WHEN c1r_t2p_t3e%NOTFOUND;

END LOOP;

COMMIT;

CLOSE c1r_t2p_t3e;



EXCEPTION

    WHEN OTHERS THEN

       e3r_2:=SQLCODE;

       MESSAGE:=SQLERRM;

       DBMS_OUTPUT.PUT_LINE('t3e_5 IS AN e3r_2 WHILE r5g u65_p1c_ma_s1c_u1d IN e5k '||MESSAGE);

       DBMS_OUTPUT.PUT_LINE(MESSAGE);

       INSERT INTO u66_e1r(u4e_2,u3g) VALUES(SYSDATE,MESSAGE);

       COMMIT;



END u65_p1c_ma_s1c_u1d;,"CREATE OR REPLACE PROCEDURE c4a_e5k.u65_p1c_ma_s1c_u1d()

PROCEDURE p1c_g1t_i3t_u6d_p3s
    (
        o4t_id  IN NUMBER,
        b3h_n2e IN VARCHAR2,
        u12t OUT r13r
    )
IS
BEGIN
    DECLARE
        s9y  VARCHAR2(4000);
        v_e7e  VARCHAR2(200);
        v_e7t_2  VARCHAR2(1000);
        v_s3e      VARCHAR2(100);
        v_s1q_p4e NUMBER;
        v_d2e_s1q   VARCHAR2 (30);
        c3t_t3l  NUMBER;
        c3t_m3h  NUMBER;
        c3t_i3t  NUMBER;
        s101 VARCHAR2(4200);



    BEGIN
        v_s3e     := 'p1c_g1t_i3t_u6d_p3s';
        s9y :=
        'SELECT a1t_i3t_p1t_n1r_s1r AS p2t_no,a1t_i3t_m1r_c2e AS m1r_c2e ,a1t_p2t_o3d AS o1j_id,a1t_p1t_m1g_p1r_s1r AS m1r_o1j_id,a1t_p2t_t2e AS TYPE,a1t_cf_c6y AS c6y_2,a1t_d1v_s4s_s1r AS s4s_8,a1t_f1f_g1p_c2e AS f1f_g1p_c2e,a1t_f2c_g1p_c2e AS f2c_g1p_c2e,a1t_p1t_c3e AS c3e,a1t_p1t_s4e AS SOURCE,a1t_c1t_c2e AS c1t_c2e,a1t_r3s_a7e AS is_r3s_a1i,a1t_c1t_t3e_a7e AS is_c1t_a1i,a1t_p2t_i5d AS is_p2t_v3d,a1t_r5s AS r5s_4,a1t_i3t_f6e AS f2e_n2e FROM a1t_i3t_m4r WHERE a1t_o1j_id = '
        ||o4t_id||' AND a1t_b3h_n2e= '''||b3h_n2e||'''';
        OPEN u12t FOR s9y;
    EXCEPTION
    WHEN no_d2a_f3d THEN
        v_e7e := SQLCODE;
        v_e7t_2 := SUBSTR (SQLERRM, 1, 199);
        INSERT
        INTO
            a1t_wf_e3r_t3e VALUES
            (
                'p1c_u4e_i3t: no_d2a_f3d',v_e7e,v_e7t_2,SYSDATE,v_s3e
            );
        COMMIT;
    WHEN OTHERS THEN
        v_e7e := SQLCODE;
        v_e7t_2 := SUBSTR (SQLERRM, 1, 199);
        INSERT
        INTO
            a1t_wf_e3r_t3e VALUES
            (
                'p1c_g1t_i3t_u6d_p3s: OTHERS',v_e7e,v_e7t_2,SYSDATE,v_s3e
            );
        COMMIT;
    END;
END p1c_g1t_i3t_u6d_p3s;
,"CREATE OR REPLACE FUNCTION p1c_g1t_i3t_u6d_p3s(

PROCEDURE ds_s5y_r4t(p2c_c2t_id IN ds_t3k_m4r.ds_c1s_id%TYPE, p2c_c1p_r4t OUT m6r, p2c_p5c_r4t OUT m6r, p2c_b7m_r4t OUT m6r, p2c_qc_r4t OUT m6r, p2c_s1e_r4t OUT m6r, p2c_rs_r4t OUT m6r, p2c_t1t_r4t OUT m6r, p2c_e3r_r4t OUT m6r)
IS
	v_m1p_q51 VARCHAR2(4000):=NULL;
	v_c41 NUMBER:=0;
    v_c42 NUMBER:=0;
	v_s1d_c3t NUMBER:=0;
