	  v_m1p_q51:=g1t_m1p_q4y(p2c_c2t_id, 'CAPTURE', 'c6e_4');
	  OPEN p2c_p5c_r4t FOR v_m1p_q51;
	  EXECUTE IMMEDIATE v_m1p_q51 INTO v_c41, v_c42;

	  v_s1d_c3t:= v_s1d_c3t + v_c41;
	  v_i3d_c3t:= v_i3d_c3t + v_c42;

	  v_m1p_q51:=g1t_m1p_q4y(p2c_c2t_id, 'p5c', 'c6e_4');
	  OPEN p2c_b7m_r4t FOR v_m1p_q51;
	  EXECUTE IMMEDIATE v_m1p_q51 INTO v_c41, v_c42;

	  v_s1d_c3t:= v_s1d_c3t + v_c41;
	  v_i3d_c3t:= v_i3d_c3t + v_c42;

	  v_m1p_q51:=g1t_m1p_q4y(p2c_c2t_id, 'b7m', 'c6e_4');
	  OPEN p2c_qc_r4t FOR v_m1p_q51;
	  EXECUTE IMMEDIATE v_m1p_q51 INTO v_c41, v_c42;
	  v_s1d_c3t:= v_s1d_c3t + v_c41;
	  v_i3d_c3t:= v_i3d_c3t + v_c42;

	  v_m1p_q51:=g1t_m1p_q4y(p2c_c2t_id, 'qc', 'c6e_4');
	  OPEN p2c_s1e_r4t FOR v_m1p_q51;
	  EXECUTE IMMEDIATE v_m1p_q51 INTO v_c41, v_c42;
	  v_s1d_c3t:= v_s1d_c3t + v_c41;
	  v_i3d_c3t:= v_i3d_c3t + v_c42;

	  v_m1p_q51:=g1t_m1p_q4y(p2c_c2t_id, 's1e', 'c6e_4');
	  OPEN p2c_rs_r4t FOR v_m1p_q51;
