	  v_s1d_c3t:= v_s1d_c3t + v_c41;
	  v_i3d_c3t:= v_i3d_c3t + v_c42;


	  v_m1p_q51:= 'SELECT ''' || v_s1d_c3t || ':' || v_i3d_c3t || '''FROM d2l';
	  OPEN p2c_t1t_r4t FOR v_m1p_q51;
	  OPEN p2c_e3r_r4t FOR SELECT 'c7d' FROM d2l;
EXCEPTION
		 WHEN OTHERS THEN
		 	  v_m1p_q51:=NULL;
			  v_m1p_q51:= SUBSTR(SQLERRM, 1, 100);
			  v_m1p_q51:= 'SELECT ' || v_m1p_q51 || ' FROM d2l';
		 	  OPEN p2c_e3r_r4t FOR v_m1p_q51;
END ds_s5y_r4t;

,"CREATE OR REPLACE FUNCTION ds_s5y_r4t(

PROCEDURE p1c_a1l_pm_m1r_l2t
(
o4t_id IN NUMBER,
b3h_n4r IN VARCHAR2,
b1z_t2e IN VARCHAR2,
m4t_2 OUT r7t_6
)
IS
BEGIN
DECLARE  
s9y  VARCHAR2(4000);
 v_e7e        VARCHAR2(200); 
 v_e7t_2        VARCHAR2(1000);
 v_s3e            VARCHAR2(100);
 v_s1q_p4e NUMBER;
 v_d2e_s1q VARCHAR2 (30);
 c3t_t3l  NUMBER;
 c3t_m3h  NUMBER;





BEGIN

  v_s3e := 'u2h_a1l_pm_s5y.p1c_a1l_pm_m1r_l2t';

    SELECT NVL(COUNT(u2h_m1r_p2t_n4r),0) INTO c3t_t3l  FROM  u2h_pm_o4t WHERE  u2h_o1j_id=p1c_a1l_pm_m1r_l2t.o4t_id AND u2h_b3h_n4r=p1c_a1l_pm_m1r_l2t.b3h_n4r AND u2h_b6s_t2e=p1c_a1l_pm_m1r_l2t.b1z_t2e; 
IF c3t_t3l > 0 THEN    

     s9y := 'SELECT  u2h_m1r_c2e , u2h_m1r_n2e  FROM u2h_pm_o4t';    

IF b3h_n4r IS NOT NULL THEN
  s9y := s9y || '  WHERE u2h_b3h_n4r = '''||b3h_n4r||''' AND u2h_o1j_id = '||o4t_id||'  AND u2h_b6s_t2e ='''||b1z_t2e||'''';

END IF;

s9y := s9y || '  GROUP BY u2h_m1r_n2e ,u2h_m1r_c2e   ORDER BY u2h_m1r_n2e ,u2h_m1r_c2e ';


 DBMS_OUTPUT.PUT_LINE(s9y);
    OPEN m4t_2 FOR s9y;




END IF;



EXCEPTION
      WHEN no_d2a_f3d
      THEN
          v_e7e := SQLCODE;
          v_e7t_2 := SUBSTR (SQLERRM, 1, 199);
          INSERT INTO u2h_e3r_t3e  VALUES('p1c_a1l_pm_m1r_l2t: no_d2a_f3d',v_e7e,v_e7t_2,SYSDATE,v_s3e);
         COMMIT;
      WHEN OTHERS
      THEN
          v_e7e := SQLCODE;
          v_e7t_2 := SUBSTR (SQLERRM, 1, 199);
          INSERT INTO u2h_e3r_t3e  VALUES('p1c_a1l_pm_m1r_l2t: OTHERS',v_e7e,v_e7t_2,SYSDATE,v_s3e);
          COMMIT;

END;
END p1c_a1l_pm_m1r_l2t;



,"CREATE OR REPLACE PROCEDURE p1c_a1l_pm_m1r_l2t(

  CREATE OR REPLACE EDITIONABLE PROCEDURE "c4a"."f1r_r4t_ah_t3t" AUTHID CURRENT_USER AS 

CURSOR c1s_f1s IS SELECT a.*,b.m4e FROM f1r_c1s_t3t a,f1r_t2e_t3t b WHERE a.t2e_id=b.t2e_id AND a.t2e_id NOT IN ('c33','c33_4','c32_2');
v_n1m NUMBER :=0;
r_f1s c1s_f1s%ROWTYPE;

BEGIN
EXECUTE IMMEDIATE 'TRUNCATE TABLE f1r_r4t_t3t';
EXECUTE IMMEDIATE 'DROP TABLE f1r_t2e_t3t';

EXECUTE IMMEDIATE 'CREATE TABLE f1r_t2e_t3t AS SELECT DISTINCT(t2e_id),CAST(''e1t_f1r_e1t_u27'' AS VARCHAR2(30)) AS m4e FROM cf_a4e_pn_m4r';
INSERT INTO f1r_t2e_t3t SELECT DISTINCT(t2e_id),'e1t_f1r_e1t_u27' FROM cf_h2t_pn_m4r;

EXECUTE IMMEDIATE 'DROP TABLE f1r_c1s_t3t';
EXECUTE IMMEDIATE 'CREATE TABLE f1r_c1s_t3t AS SELECT a.o1j_id,s_c1s_l3l,t2e_id,c1t_d5y_n2e,c1t_c1s_c7y_n2e,c1t_c1s_d5y_n2e 
 FROM c1s_c1s_t3e a,c1s_c1t_c6y b WHERE a.o1j_id=b.c1t_c3s_id';

OPEN c1s_f1s;
LOOP
 FETCH c1s_f1s INTO r_f1s;
 EXIT WHEN c1s_f1s%NOTFOUND;
 DBMS_OUTPUT.PUT_LINE(r_f1s.s_c1s_l3l||','||r_f1s.c1t_d5y_n2e); 


DECLARE
 l_c4r SYS_REFCURSOR;
 l_c2s VARCHAR2(32000);
 l_q21 VARCHAR2(32000);q25 VARCHAR2(32000);
 l_q22 VARCHAR2(32000);
 tr VARCHAR2(32000);hd VARCHAR2(32000);hd_ln VARCHAR2(32);tr_ln NUMBER(10);

tr_b3c NUMBER(10);tr_d4l NUMBER(10);tr_d4l_c1p NUMBER(10);tr_d4l_ed NUMBER(10);tr_d4l_e1c NUMBER(10);

